import XCTest

final class DriveTests: XCTestCase {
    func testOpenLikes() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")

        let openButton = app.alerts.buttons["Open"]
        let sbOpen = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 5) {
            openButton.tap()
        } else if sbOpen.waitForExistence(timeout: 2) {
            sbOpen.tap()
        }
        sleep(3)
        app.activate()
        sleep(2)

        let likes = app.buttons["Likes"].firstMatch
        let likesText = app.staticTexts["Likes"].firstMatch
        let profileTab = app.tabBars.buttons["Profile"].firstMatch
        if !likes.exists && profileTab.waitForExistence(timeout: 5) {
            profileTab.tap()
            sleep(2)
        }
        if likes.waitForExistence(timeout: 8) {
            likes.tap()
        } else if likesText.waitForExistence(timeout: 2) {
            likesText.tap()
        }
        sleep(2)
        let shot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        shot.lifetime = .keepAlways
        add(shot)
    }
}

